'use client';
import React from 'react';
import {
	Table,
	TableHeader,
	TableColumn,
	TableBody,
	TableRow,
	TableCell,
	Chip,
	Spinner,
} from '@nextui-org/react';
import useGameData from '@/app/hooks/useGameData';

const columns = [
	{ name: 'HOME', uid: 'home' },
	{ name: 'AWAY', uid: 'away' },
	{ name: 'SCORE', uid: 'score' },
	{ name: 'LOCATION', uid: 'location' },
	{ name: 'DATE', uid: 'date' },
];

export default function StatsTable() {
	const { games, isLoading, error } = useGameData();

	const renderCell = React.useCallback((game: any, columnKey: string) => {
		const cellValue = game[columnKey];

		switch (columnKey) {
			case 'score':
				return (
					<Chip
						className='capitalize'
						color={game.result === 'win' ? 'success' : 'danger'}
						size='sm'
						variant='flat'>
						{cellValue}
					</Chip>
				);
			default:
				return cellValue;
		}
	}, []);

	if (isLoading) {
		return <Spinner label='Loading game data...' />;
	}

	if (error) {
		return <div>Error: {error.message}</div>;
	}

	if (!games) {
		return <div>No game data available</div>;
	}

	return (
		<Table aria-label='University of Texas Longhorns 2023 Season Record'>
			<TableHeader columns={columns}>
				{(column) => (
					<TableColumn key={column.uid} align='center'>
						{column.name}
					</TableColumn>
				)}
			</TableHeader>
			<TableBody items={games}>
				{(item) => (
					<TableRow key={item.id}>
						{(columnKey) => (
							<TableCell>{renderCell(item, columnKey as string)}</TableCell>
						)}
					</TableRow>
				)}
			</TableBody>
		</Table>
	);
}
